"""Train a tiny decision tree to choose forward / left / right from heading error."""
from pathlib import Path
import math
import joblib
from sklearn.tree import DecisionTreeClassifier

root = Path(__file__).resolve().parent
# Training examples generated by a simple teacher rule, not downloaded data.
angles = [(-math.pi + i * 2 * math.pi / 720) for i in range(721)]
X = [[a] for a in angles]
y = ["RIGHT" if a < -0.18 else "LEFT" if a > 0.18 else "FORWARD" for a in angles]
model = DecisionTreeClassifier(max_depth=3, random_state=0)
model.fit(X, y)
joblib.dump(model, root / "direction_model.joblib")
print("Saved:", root / "direction_model.joblib")
for a in (-1.0, 0.0, 1.0):
    print(f"angle={a:+.1f} rad -> {model.predict([[a]])[0]}")
print("Training accuracy:", model.score(X, y))
